def simple_path_fill(special_positions):
    """Fill cells between pairs of special cells in all alignments"""
    filled = set()
    for i, (r1, c1) in enumerate(special_positions):
        for r2, c2 in special_positions[i+1:]:
            r_diff = r2 - r1
            c_diff = c2 - c1

            # Horizontal
