                fill_between = range(min(c1, c2), max(c1, c2) + 1)
                for c in fill_between:
                    filled.add((r1, c))

            # Vertical
            elif c_diff == 0:
                fill_between = range(min(r1, r2), max(r1, r2) + 1)
                for r in fill_between:
                    filled.add((r, c1))

            # Diagonal
            elif abs(r_diff) == abs(c_diff):
                steps = max(abs(r_diff), abs(c_diff))
                r_step = r_diff // steps
                c_step = c_diff // steps
                for step in range(1, steps):
                    r = r1 + step * r_step
